    const GLOBAL_KATEX_MACROS = {
        "\\R": "\\mathbb{R}",
        "\\N": "\\mathbb{N}",
        "\\E": "\\mathbb{E}",
        "\\Prob": "\\mathbb{P}",
        "\\sP": "\\mathbb{P}"
    };

    function mergeKatexOptions(options) {
        const merged = options || {};
        merged.macros = Object.assign({}, GLOBAL_KATEX_MACROS, merged.macros || {});
        merged.globalGroup = true;
        return merged;
    }

    function patchDMath() {
        if (!window.DMath) {
            return false;
        }

        const originalCallback = DMath.katexLoadedCallback.bind(DMath);
        DMath.katexLoadedCallback = function () {
            DMath._katexOptions = mergeKatexOptions(DMath._katexOptions);
            originalCallback();
        };

        Object.defineProperty(DMath, "katexOptions", {
            configurable: true,
            enumerable: true,
            get() {
                return DMath._katexOptions;
            },
            set(options) {
